"""Symbolic type visitors: declaration order, harness layout and recovery.

``declaration_postorder`` collects the C declaration names reachable from a
type, ``LayoutBuilder`` implements the documented ``MainBuilder`` numbering
convention (one increasing ``xN`` per visited bool/char/int/enum/string
buffer/array/struct) and ``ValueReader`` recovers concrete values from a
decoded KTEST inventory using exactly the same traversal.
"""

from .ast import (Alias, Array, Bool, Char, Enum, Int, String, Struct, Type,
                  Void)


class TestError(Exception):
    """Raised when a recorded test disagrees with the compiled inventory."""


class LeafSpec(object):
    """Description of one symbolic leaf object and its byte width."""

    __slots__ = ('kind', 'width', 'limit', 'values')

    def __init__(self, kind, width, limit=0, values=None):
        self.kind = kind
        self.width = width
        self.limit = limit
        self.values = values

    def read(self, data):
        if len(data) != self.width:
            raise TestError('object width mismatch')
        value = int.from_bytes(data, 'little')
        if value > self.limit:
            raise TestError('leaf value out of range')
        kind = self.kind
        if kind == 'bool':
            return value == 1
        if kind == 'char':
            return chr(value)
        if kind == 'enum':
            return self.values[value]
        return value


BOOL_SPEC = LeafSpec('bool', 1, 1)
CHAR_SPEC = LeafSpec('char', 1, 255)


def int_spec(bits):
    return LeafSpec('int', int_width(bits), (1 << bits) - 1)


def enum_spec(values):
    return LeafSpec('enum', 4, len(values) - 1, tuple(values))


class TypeBuilder(object):
    """Converts an Eywa type to a C type."""

    @staticmethod
    def build(type):
        return TypeBuilder().visit(type)

    def visit_Void(self, node):
        return 'void', ''

    def visit_Bool(self, node):
        return 'bool', ''

    def visit_Char(self, node):
        return 'char', ''

    def visit_Int(self, node):
        if node.bits == 64:
            return 'uint64_t', ''
        if node.bits == 32:
            return 'uint32_t', ''
        if node.bits == 16:
            return 'uint16_t', ''
        if node.bits == 8:
            return 'uint8_t', ''
        return 'unsigned', ': %d' % node.bits

    def visit_String(self, node):
        return 'char*', ''

    def visit_Enum(self, node):
        return node.name, ''

    def visit_Array(self, node):
        left, right = self.visit(node.element_type)
        return left, '%s[%d]' % (right, node.size)

    def visit_Struct(self, node):
        return node.name, ''

    def visit_Alias(self, node):
        return node.name, ''

    def visit(self, node):
        name = 'visit_' + node.__class__.__name__
        return getattr(self, name)(node)


class DefinitionBuilder(object):
    """Builds the C type definition (if any) needed for an Eywa type."""

    @staticmethod
    def build(type):
        return DefinitionBuilder().visit(type)

    def visit_Void(self, node):
        return None

    def visit_Bool(self, node):
        return None

    def visit_Char(self, node):
        return None

    def visit_Int(self, node):
        return None

    def visit_String(self, node):
        return None

    def visit_Enum(self, node):
        return 'typedef enum { %s } %s;\n' % (', '.join(node.values), node.name)

    def visit_Array(self, node):
        return None

    def visit_Struct(self, node):
        parts = []
        for field_name, field in node.fields.items():
            left, right = TypeBuilder.build(field)
            parts.append('%s %s%s;' % (left, field_name, right))
        return 'typedef struct { %s } %s;\n' % (' '.join(parts), node.name)

    def visit_Alias(self, node):
        left, right = TypeBuilder.build(node.type)
        return 'typedef %s %s%s;\n' % (left, node.name, right)

    def visit(self, node):
        name = 'visit_' + node.__class__.__name__
        return getattr(self, name)(node)


class TypeCollector(object):
    """Recursively extracts the Eywa sub-types of a type."""

    def __init__(self, result):
        self.result = result

    def visit(self, node):
        name = 'visit_' + node.__class__.__name__
        return getattr(self, name)(node)

    def visit_Void(self, node):
        self.result.append(node)

    def visit_Bool(self, node):
        self.result.append(node)

    def visit_Char(self, node):
        self.result.append(node)

    def visit_Int(self, node):
        self.result.append(node)

    def visit_String(self, node):
        self.result.append(node)

    def visit_Enum(self, node):
        self.result.append(node)

    def visit_Array(self, node):
        self.visit(node.element_type)
        self.result.append(node)

    def visit_Struct(self, node):
        for field in node.fields.values():
            self.visit(field)
        self.result.append(node)

    def visit_Alias(self, node):
        self.visit(node.type)
        self.result.append(node)

    @staticmethod
    def collect(type, results):
        TypeCollector(results).visit(type)


def declaration_postorder(type, out, seen):
    """Append reachable enum/struct/alias declaration names, children first.

    ``out`` receives each declaration name once; ``seen`` is the set of names
    already emitted.  Primitive, array and string definition names are not C
    declaration names and never appear.
    """
    if isinstance(type, Alias):
        declaration_postorder(type.type, out, seen)
        if type.name not in seen:
            seen.add(type.name)
            out.append(type.name)
        return
    if isinstance(type, Struct):
        for field in type.fields.values():
            declaration_postorder(field, out, seen)
        if type.name not in seen:
            seen.add(type.name)
            out.append(type.name)
        return
    if isinstance(type, Array):
        declaration_postorder(type.element_type, out, seen)
        return
    if isinstance(type, String):
        return
    if isinstance(type, Enum):
        if type.name not in seen:
            seen.add(type.name)
            out.append(type.name)
        return
    if isinstance(type, (Bool, Char, Int, Void)):
        return
    raise TestError('unsupported type ' + type.__class__.__name__)


class LayoutBuilder(object):
    """Reservation visitor producing the documented harness layout."""

    def __init__(self):
        self.number = 0
        self.slots = []
        self.inventory = {}

    def _next(self):
        number = self.number
        self.number += 1
        return 'x%d' % number

    def scalar(self, spec, path):
        name = self._next()
        self.slots.append([name, path, spec.width])
        self.inventory[name] = spec
        return name

    def composite(self, path):
        # Zero-length and nested composites still reserve their own id, but a
        # composite is not a symbolic object.
        return self._next()

    def string_value(self, chars):
        return None

    def reserve_flag(self):
        name = self._next()
        self.inventory[name] = BOOL_SPEC
        return name


#: Historic name of :class:`LayoutBuilder`.
MainBuilder = LayoutBuilder


def recover_string(chars):
    """Recover the value of a symbolic string from its character objects."""
    for index, char in enumerate(chars):
        if char == '\x00':
            return ''.join(chars[:index])
    return ''.join(chars)


class ValueReader(object):
    """Recovery visitor reading concrete values from a decoded inventory."""

    def __init__(self, objects):
        self.objects = objects
        self.number = 0

    def _next(self):
        number = self.number
        self.number += 1
        return 'x%d' % number

    def scalar(self, spec, path):
        name = self._next()
        data = self.objects.get(name)
        if data is None:
            raise TestError('missing object ' + name)
        return spec.read(data)

    def composite(self, path):
        return self._next()

    def string_value(self, chars):
        return recover_string(chars)


#: Historic name of :class:`ValueReader`.
ResultReader = ValueReader


def walk_type(type, path, visitor):
    """Visit ``type`` in harness order with the given reservation visitor."""
    inner = Type.inner(type)
    if isinstance(inner, Bool):
        return visitor.scalar(BOOL_SPEC, path)
    if isinstance(inner, Char):
        return visitor.scalar(CHAR_SPEC, path)
    if isinstance(inner, Int):
        return visitor.scalar(int_spec(inner.bits), path)
    if isinstance(inner, Enum):
        return visitor.scalar(enum_spec(inner.values), path)
    if isinstance(inner, String):
        visitor.composite(path)
        chars = [visitor.scalar(CHAR_SPEC, path + [index])
                 for index in range(inner.maxsize)]
        return visitor.string_value(chars)
    if isinstance(inner, Array):
        visitor.composite(path)
        return [walk_type(inner.element_type, path + [index], visitor)
                for index in range(inner.size)]
    if isinstance(inner, Struct):
        visitor.composite(path)
        return {field: walk_type(field_type, path + [field], visitor)
                for field, field_type in inner.fields.items()}
    raise TestError('void has no symbolic representation')
